// Завершение курса: хадж, Медина и два итоговых урока.
(function () {
  const lessons = {
    46:{page:"123–124",ru:{intro:"После Арафата путь продолжается через Муздалифу и Мину. На схеме важно увидеть, где и когда совершается каждое действие.",brief:["Ночёвка в Муздалифе, переход в Мину и бросание камешков показаны на страницах 123–124.","Десятый день отличается от следующих: меняется число столбов, в которые бросают камешки."],title:"От Муздалифы к трём столбам",points:["После захода солнца на Арафате паломники направляются в Муздалифу, где проводят ночь и готовятся к следующему дню.","На десятый день в Мине бросают семь камешков в большой столб. Каждый камешек бросают отдельно.","В последующие дни бросание совершают уже у трёх столбов: по семь камешков у каждого, в установленном порядке.","Камешки и место не заменяют намерение обряда: учебник связывает действие с определёнными днями хаджа.","Не складывайте все числа в одно правило. Запомните сначала день, затем число столбов, затем семь бросков у каждого."],explain:[{title:"Два разных маршрута",text:"Арафат → Муздалифа — переход вечером девятого дня. Муздалифа → Мина — путь к обрядам следующего дня."},{title:"Почему счёт различается",text:"Десятого дня речь об одном столбе; далее о трёх. Число семь относится к каждому столбу, а не ко всему дню."},{title:"Порядок важнее запоминания суммы",text:"Схема на странице 124 помогает следить за днями. Если число забыто, возвращайтесь к дню и месту, а не к общей сумме камешков."}],further:[{title:"Проверьте по книге",text:"Найдите на странице 124 отдельное описание десятого дня и описание следующих дней. Отметьте разницу в числе столбов."},{title:"Следующий этап",text:"После бросания камешков книга рассказывает о жертвоприношении и укорачивании волос — это тема урока 47."}],checks:["10-й день: большой столб, семь отдельных бросков.","Следующие дни: три столба, по семь у каждого."]},tt:{intro:"Гарафаттан соң юл Мөздәлифә аша Минага бара. Схемада һәр гамәлнең урынын һәм көнен аерып күрү мөһим.",brief:["123–124 нче битләрдә Мөздәлифәдә куну, Минага күчү һәм таш ату тәртибе бирелгән.","Унынчы көн белән киләсе көннәр аерыла: таш атыла торган баганалар саны үзгәрә."],title:"Мөздәлифәдән өч баганага кадәр",points:["Гарафатта кояш баегач, хаҗилар Мөздәлифәгә бара; анда төнне үткәреп, киләсе көнгә әзерләнәләр.","Унынчы көнне Минада зур баганага җиде таш атыла. Һәр таш аерым атыла.","Киләсе көннәрдә билгеләнгән тәртиптә өч багананың һәркайсына җидешәр таш атыла.","Таш һәм урын гына җитми: китап бу гамәлне хаҗның билгеле көннәренә бәйли.","Барлык саннарны бер кагыйдәгә кушмагыз: башта көнне, аннары баганалар санын, соңыннан һәрберсенә җиде ташны истә калдырыгыз."],explain:[{title:"Ике күчеш",text:"Гарафат → Мөздәлифә — тугызынчы көн кичендә. Мөздәлифә → Мина — киләсе көн йолаларына күчеш."},{title:"Сан ни өчен үзгәрә",text:"Унынчы көндә бер багана, аннан соң өч багана турында сүз бара. Җиде саны һәр баганага карый."},{title:"Тәртипне аңлау",text:"124 нче биттәге аңлатма көннәрне күзәтергә ярдәм итә. Сан онытылса, гомуми таш санын түгел, көн белән урынны искә төшерегез."}],further:[{title:"Китаптан тикшерегез",text:"124 нче биттә унынчы көн белән киләсе көннәрнең тасвирламасын табып, баганалар санын чагыштырыгыз."},{title:"Киләсе этап",text:"Таш атудан соң китап корбан һәм чәч кыскарту турында сөйли. Бу — 47 нче дәрес."}],checks:["10 нчы көн: зур баганага җиде аерым таш.","Киләсе көннәр: өч багананың һәркайсына җидешәр таш."]}},
    47:{page:"125–126",ru:{intro:"Завершение обрядов связано с жертвоприношением и волосами. Их порядок и положение зависят от вида хаджа и паломника.",brief:["На страницах 125–126 различаются ваджиб и сунна жертвоприношения.","Затем книга объясняет бритьё или укорачивание волос и особое правило для женщин."],title:"Жертвоприношение и выход из ихрама",points:["При таматту‘ и киране жертвоприношение в учебнике названо ваджибом; при ифраде — сунной.","Паломник проверяет свой вид хаджа прежде, чем переносить на себя правило другого вида.","После установленного обряда мужчина бреет голову или укорачивает волосы; книга отдельно отмечает достоинство бритья.","Женщина волосы не бреет: она укорачивает их. Одного общего слова «постричься» для обоих случаев недостаточно.","Эти действия связаны с выходом из состояния ихрама, но не отменяют оставшиеся обряды хаджа."],explain:[{title:"Сначала вид хаджа",text:"Ифрад, таматту‘ и киран различались в уроке 42. Здесь это различие помогает определить положение жертвоприношения."},{title:"Затем действие с волосами",text:"Последовательность на страницах 125–126 показывает переход от обряда к изменению состояния паломника."},{title:"Для женщин отдельная строка",text:"Женщине предписывается укорачивание волос. Схема намеренно не ставит бритьё как альтернативу для неё."}],further:[{title:"Сравните два случая",text:"Два паломника совершили ифрад и таматту‘. Одинаково ли в книге оценивается их жертвоприношение? Найдите две строки на странице 125."},{title:"Что ещё остаётся",text:"Выход из ихрама не означает, что можно забыть таваф и другие действия, предусмотренные выбранным видом хаджа."}],checks:["Таматту‘ / киран и ифрад различаются по положению жертвоприношения.","Женщины укорачивают волосы, не бреют голову."]},tt:{intro:"Хаҗ гамәлләренең ахыры корбан һәм чәч белән бәйле. Аларның тәртибе хаҗ төренә һәм хаҗ кылучыга карап аерыла.",brief:["125–126 нчы битләр корбанның вәҗиб һәм сөннәт булуын аера.","Аннары китап чәчне алу яки кыскартуны, хатын-кызлар өчен аерым кагыйдәне аңлата."],title:"Корбан һәм ихрамнан чыгу",points:["Тәмәттугъ һәм кыйран хаҗында китап корбанны вәҗиб, ифрадта исә сөннәт дип атый.","Хаҗи үзенә башка төр хаҗның кагыйдәсен күчергәнче, кайсы төрне үтәвен ачыклый.","Билгеләнгән гамәлдән соң ир-ат чәчен кыра яки кыскарта; китап кырдыруның фазыйләтен аерым әйтә.","Хатын-кыз чәчен кырмый, ә кыскарта. Ике очракка да «чәч кистерү» дигән гомуми сүз җитми.","Бу гамәлләр ихрам хәленнән чыгу белән бәйле, әмма хаҗның калган гамәлләрен юкка чыгармый."],explain:[{title:"Башта хаҗ төре",text:"Ифрад, тәмәттугъ, кыйран 42 нче дәрестә аерылды. Монда шул аерма корбанның хөкемен аңларга ярдәм итә."},{title:"Аннары чәч белән гамәл",text:"125–126 нчы битләр йола белән хаҗ хәленең үзгәрүе арасындагы бәйләнешне күрсәтә."},{title:"Хатын-кызларга аерым кагыйдә",text:"Алар чәчне кыскарталар. Схемада кырдыру хатын-кыз өчен икенче вариант итеп бирелми."}],further:[{title:"Ике хәлне чагыштырыгыз",text:"Бер хаҗи ифрад, икенчесе тәмәттугъ кыла. Китапта корбаннары бер үк дәрәҗәдәме? 125 нче биттән табыгыз."},{title:"Нәрсә кала",text:"Ихрамнан чыгу сайланган хаҗ төрендәге калган таваф һәм башка гамәлләрне онытырга мөмкин дигән сүз түгел."}],checks:["Тәмәттугъ / кыйран белән ифрадта корбан хөкеме аерыла.","Хатын-кызлар чәчен кыскарта, башын кырмый."]}},
    48:{page:"128–129",ru:{intro:"Учебник завершает раздел хаджа посещением Медины и мечети Пророка ﷺ. Это отдельное посещение со своим достоинством и этикетом.",brief:["Страницы 128–129 рассказывают о достоинстве мечети Пророка ﷺ и местах посещения.","Медину важно отличать от обязательных обрядов хаджа в Мекке, Мине и на Арафате."],title:"Медина: посещение и уважение",points:["Посещение Медины — благородное дело; оно не является одним из трёх фардов хаджа, перечисленных в уроке 40.","В мечети Пророка ﷺ паломник совершает намаз и соблюдает спокойствие и уважение к месту.","Книга упоминает приветствие Пророка ﷺ; этикет исключает шум и теснение других посетителей.","Посещения исторических мест Медины помогают помнить историю, но не заменяют таваф, са‘й или стояние на Арафате.","Раздел удобно читать как завершение путешествия: обряд хаджа и посещение Медины имеют разный статус."],explain:[{title:"Обряд и посещение",text:"Вопрос «будет ли хадж действителен?» решают по его условиям и фардам. Посещение Медины обсуждают отдельно."},{title:"Как вести себя в мечети",text:"Сосредоточенность в намазе, спокойное приветствие и уважение к окружающим помогают сохранить достоинство места."},{title:"Не смешивать города",text:"Таваф совершается у Каабы в Мекке, Арафат и Мина — места хаджа; мечеть Пророка ﷺ находится в Медине."}],further:[{title:"Проверьте карту",text:"Назовите, какие места входят в маршрут обрядов хаджа, а какое посещают после или вне него."},{title:"Заключение раздела",text:"Следующие два урока соберут темы курса в общую систему и помогут проверить понимание, а не только память чисел."}],checks:["Посещение Медины отделяют от фардов хаджа.","Этикет мечети Пророка ﷺ требует спокойствия и уважения."]},tt:{intro:"Китап хаҗ бүлеген Мәдинә һәм Пәйгамбәр ﷺ мәчетен зиярәт итү белән тәмамлый. Бу — үз фазыйләте һәм әдәбе булган аерым сәфәр.",brief:["128–129 нчы битләр Пәйгамбәр ﷺ мәчетенең фазыйләтен һәм зиярәт урыннарын аңлата.","Мәдинәне Мәккә, Мина һәм Гарафаттагы хаҗ гамәлләреннән аеру мөһим."],title:"Мәдинә: зиярәт һәм хөрмәт",points:["Мәдинәне зиярәт итү — күркәм гамәл; ул 40 нчы дәрестә санап үтелгән хаҗның өч фарызына керми.","Пәйгамбәр ﷺ мәчетендә намаз укыйлар, тынычлык һәм хөрмәт саклыйлар.","Китап Пәйгамбәргә ﷺ сәлам бирүне әйтә; әдәп шау-шу һәм башкаларны кысрыклауны рөхсәт итми.","Мәдинәнең тарихи урыннарын күрү тарихны искә төшерә, әмма таваф, сәгый яки Гарафатта торуны алыштырмый.","Бүлек сәфәр ахыры буларак укыла: хаҗ йоласы белән Мәдинә зиярәтенең хөкеме төрле."],explain:[{title:"Йола һәм зиярәт",text:"«Хаҗ дөресме?» дигән сорау шартлар һәм фарызлар буенча хәл ителә. Мәдинә зиярәте аерым карала."},{title:"Мәчеттәге әдәп",text:"Намазда игътибар, тыныч сәлам һәм тирәдәгеләргә хөрмәт урынның дәрәҗәсен саклый."},{title:"Шәһәрләрне бутамагыз",text:"Таваф Мәккәдә Кәгъбә янында; Гарафат белән Мина — хаҗ урыннары; Пәйгамбәр ﷺ мәчете Мәдинәдә."}],further:[{title:"Картадан тикшерегез",text:"Кайсы урыннар хаҗ йолалары юлында, ә кайсысы аннан соң яки аерым зиярәт ителә?"},{title:"Бүлек ахыры",text:"Киләсе ике дәрес курс темаларын берләштереп, саннарны гына түгел, аңлауны да тикшерергә ярдәм итә."}],checks:["Мәдинә зиярәте хаҗ фарызларыннан аерым.","Пәйгамбәр ﷺ мәчетендә тынычлык һәм хөрмәт саклана."]}},
    49:{page:"2–130",ru:{intro:"Перед итоговым уроком соберём весь путь курса в одну карту. Вспоминаем не отдельные ответы теста, а связи между условиями, действиями и результатом.",brief:["Страницы учебника от очищения до хаджа образуют пять больших тематических разделов.","Повторение помогает увидеть, какую страницу открыть, если возник вопрос в реальной ситуации."],title:"Пять разделов курса на одной карте",points:["Очищение: вода, вуду, гусль и таяммум. Сначала выясняют состояние и доступное средство очищения.","Намаз: время, условия, состав ракаата и действия, меняющие порядок молитвы. Условия проверяют до начала.","Пост: намерение, время воздержания, уважительные причины и восполнение. Различают пропуск и нарушение поста.","Закят: имущество, нисаб, доля и получатель. Число без вида имущества и условий ещё не даёт решения.","Хадж: вид паломничества, фарды, ваджибы и маршрут дней. Мекка, Арафат, Муздалифа и Мина имеют разные роли."],explain:[{title:"Как искать ответ",text:"Сначала назовите раздел, затем вопрос: условие, обязательное действие, желательное действие или последствие ошибки."},{title:"Порядок проверки",text:"Для каждого поклонения полезна цепочка: кому предписано → когда → при каких условиях → как выполнить."},{title:"Числа с контекстом",text:"Семь переходов са‘й и семь камешков — разные действия. Нисаб и процент закята также относятся к разным вопросам."}],further:[{title:"Пять коротких ситуаций",text:"Нет воды; пропущен ракаат; появилась причина не поститься; есть имущество; паломник прибыл к микату. Найдите для каждого случая раздел учебника."},{title:"Подготовка к итогу",text:"В следующем уроке разберите трудные пары понятий и пройдите проверку курса. Ошибку используйте как указатель на нужную страницу."}],checks:["Сначала определяем раздел и вид вопроса.","Цифры запоминаем вместе с их условиями и действием."]},tt:{intro:"Соңгы дәрес алдыннан курс юлын бер картага җыябыз. Тест җавапларын гына түгел, шарт, гамәл һәм нәтиҗә арасындагы бәйләнешне искә төшерәбез.",brief:["Тәһарәттән хаҗга кадәр китап битләре биш зур темага бүленә.","Кабатлау тормыштагы сорау өчен кайсы битне ачарга кирәклеген күрсәтә."],title:"Курсның биш бүлеге — бер картада",points:["Пакьләнү: су, вуду, госел һәм тәяммүм. Башта хәлне һәм пакьләнү чарасын ачыклыйбыз.","Намаз: вакыт, шартлар, рәкәгать төзелеше һәм тәртипне үзгәртә торган хәлләр. Шартлар башлаганчы тикшерелә.","Ураза: ният, тыелу вакыты, гозерләр һәм каза. Калдырылган ураза белән бозылган уразаны аерабыз.","Зәкят: мал, нисап, өлеш һәм алучы. Мал төре белән шартлар билгесез булса, сан гына җавап бирми.","Хаҗ: төре, фарызлар, вәҗибләр һәм көннәр юлы. Мәккә, Гарафат, Мөздәлифә, Мина — төрле урыннар."],explain:[{title:"Җавапны ничек эзләргә",text:"Башта бүлекне, аннары сорау төрен әйтегез: шартмы, мәҗбүри гамәлме, сөннәтме, хатаның нәтиҗәсеме?"},{title:"Тикшерү тәртибе",text:"Һәр гыйбадәт өчен чылбыр файдалы: кемгә тиеш → кайчан → нинди шартта → ничек үтәлә."},{title:"Саннарның урыны",text:"Сәгыйнең җиде юлы һәм җиде таш — төрле гамәл. Нисап белән зәкят өлеше дә ике башка сорау."}],further:[{title:"Биш кыска хәл",text:"Су юк; рәкәгатькә соңга калды; ураза тотмаска гозер бар; мал тупланды; хаҗи микатка килде. Һәркайсына китап бүлеген табыгыз."},{title:"Соңгы дәрескә әзерлек",text:"Киләсе дәрестә бутала торган төшенчәләрне чагыштырыгыз һәм курс тикшерүен үтегез. Хата кирәкле битне күрсәтсен."}],checks:["Башта бүлек белән сорау төрен ачыклыйбыз.","Саннарны шарт һәм гамәл белән бергә истә калдырабыз."]}},
    50:{page:"2–130",ru:{intro:"Итог курса — возможность проверить, как вы применяете знания. Перед тестом разберите различия, которые чаще всего смешивают.",brief:["Финальное повторение охватывает весь учебник и уже изученные уроки.","На каждый вопрос ищите основание в теме, а не угадывайте по знакомому слову."],title:"Итог: от знания правила к выбору действия",points:["Условие и фард: условие подготавливают до поклонения, фард составляет его необходимую часть. Не меняйте их местами.","Фард, ваджиб и сунна: эти слова обозначают разное положение действия в описании книги. Проверяйте конкретный раздел.","Причина и следствие: отсутствие воды ведёт к вопросу о таяммуме; ошибка в намазе — к вопросу о саджда саху.","Время и место: у поста важны границы дня, у намаза — наступление времени, у хаджа — микат и дни обрядов.","Правило и пример: цифру или схему можно применять лишь после проверки условий, для которых она приведена."],explain:[{title:"Шаг 1 · определите тему",text:"Очищение, намаз, пост, закят или хадж. Это сокращает поиск ответа в учебнике."},{title:"Шаг 2 · уточните обстоятельства",text:"Кто действует, когда и где? Есть ли вода, путь, нисаб, время или установленное место?"},{title:"Шаг 3 · объясните решение",text:"Назовите правило своими словами и укажите, почему оно подходит к ситуации. Так проверяется понимание."}],further:[{title:"Если ответ неверен",text:"Вернитесь к соответствующему уроку и найдите, какое условие вы пропустили. Повторное прохождение нужно для обучения."},{title:"После курса",text:"Сохраните карту тем из урока 49 как указатель к учебнику. Подробный вопрос открывайте в соответствующем разделе."}],checks:["Перед ответом определите тему, условия и действие.","После проверки вернитесь к ошибкам и разберите их по учебнику."]},tt:{intro:"Курс ахыры — белемне ничек куллануыгызны тикшерү мөмкинлеге. Тест алдыннан еш бутала торган аермаларны кабатлагыз.",brief:["Соңгы кабатлау бөтен китапны һәм өйрәнелгән дәресләрне колачлый.","Һәр сорауда таныш сүзгә карап фаразламыйча, темадан нигез эзләгез."],title:"Йомгак: кагыйдәне белүдән гамәл сайлауга",points:["Шарт һәм фарыз: шарт гыйбадәт алдыннан әзерләнә, фарыз — аның кирәкле өлеше. Аларны алыштырмагыз.","Фарыз, вәҗиб, сөннәт: китапта бу сүзләр гамәлнең төрле дәрәҗәсен белдерә. Тиешле бүлекне тикшерегез.","Сәбәп һәм нәтиҗә: су булмавы тәяммүм соравына, намаздагы хата сәһү сәҗдәсенә алып килә.","Вакыт һәм урын: уразада көн чиге, намазда вакыт керүе, хаҗда микат белән йолалар көне мөһим.","Кагыйдә һәм мисал: санны яки схеманы, аның шартларын тикшергәннән соң гына кулланып була."],explain:[{title:"1 нче адым · теманы билгеләгез",text:"Пакьләнү, намаз, ураза, зәкят яки хаҗ. Бу китаптан җавап эзләүне җиңеләйтә."},{title:"2 нче адым · хәлне ачыклагыз",text:"Кем, кайчан, кайда? Су, сәфәр, нисап, вакыт яки билгеләнгән урын бармы?"},{title:"3 нче адым · нәтиҗәне аңлатыгыз",text:"Кагыйдәне үз сүзләрегез белән әйтеп, ни өчен бу хәлгә туры килүен күрсәтегез."}],further:[{title:"Җавап ялгыш булса",text:"Тиешле дәрескә кайтып, кайсы шартны калдырганыгызны табыгыз. Кабат үтү өйрәнүгә хезмәт итә."},{title:"Курстан соң",text:"49 нчы дәрестәге темалар картасын китапка күрсәткеч итеп саклагыз. Тулы сорауны тиешле бүлектән ачыгыз."}],checks:["Җавап алдыннан тема, шарт һәм гамәлне билгеләгез.","Тикшерүдән соң хаталарны китап буенча аңлагыз."]}}
  };
  window.FIQH_LESSON_CONTENT = Object.assign(window.FIQH_LESSON_CONTENT || {}, lessons);
})();
